import { z } from "zod";
import { TimestampMsSchema, VersionIdSchema } from "./common.ts";
import { ControllerSessionSchema, ControllerSnapshotSchema } from "./control.ts";
import { ActorIdSchema } from "./control-identifiers.ts";
import { EvidenceCandidateSchema } from "./private-evidence.ts";
import {
  CaptureDeviceIdSchema,
  CaptureGrantIdSchema,
  ConsentRecordIdSchema,
  PublicationAuthorityIdSchema,
} from "./private-identifiers.ts";
import { PublicCardRevisionSchema } from "./public-identifiers.ts";
import { AudienceSnapshotSchema, PublicStageSessionSchema } from "./public-protocol.ts";
import {
  PresentationSessionEpochSchema,
  PresentationSessionIdSchema,
} from "./session-identifiers.ts";

const SessionIdentityShape = {
  presentationSessionId: PresentationSessionIdSchema,
  presentationSessionEpoch: PresentationSessionEpochSchema,
} as const;

export const PublicationAuthoritySchema = z
  .object({
    authorityId: PublicationAuthorityIdSchema,
    ...SessionIdentityShape,
    actorId: ActorIdSchema,
    policyVersion: VersionIdSchema,
    expiresAtMs: TimestampMsSchema,
  })
  .strict();

export const CaptureGrantSchema = z
  .object({
    captureGrantId: CaptureGrantIdSchema,
    ...SessionIdentityShape,
    actorId: ActorIdSchema,
    captureDeviceId: CaptureDeviceIdSchema,
    consentRecordId: ConsentRecordIdSchema,
    issuedAtMs: TimestampMsSchema,
    expiresAtMs: TimestampMsSchema,
  })
  .strict()
  .refine((grant) => grant.expiresAtMs > grant.issuedAtMs, {
    message: "capture grant must expire after it is issued",
  });

export const PublisherSessionSchema = z
  .object({
    role: z.literal("PUBLISHER"),
    ...SessionIdentityShape,
    actorId: ActorIdSchema,
    authority: PublicationAuthoritySchema,
  })
  .strict();

export const PublisherSnapshotSchema = z
  .object({
    role: z.literal("PUBLISHER"),
    ...SessionIdentityShape,
    publicCardRevision: PublicCardRevisionSchema,
    candidates: z.array(EvidenceCandidateSchema),
  })
  .strict();

export const RoleSessionSchema = z.discriminatedUnion("role", [
  ControllerSessionSchema,
  PublicStageSessionSchema,
  PublisherSessionSchema,
]);
export const RoleSnapshotSchema = z.discriminatedUnion("role", [
  ControllerSnapshotSchema,
  AudienceSnapshotSchema,
  PublisherSnapshotSchema,
]);

export function authorizeRoleSnapshot(role: unknown, snapshot: unknown): boolean {
  const parsedSnapshot = RoleSnapshotSchema.safeParse(snapshot);
  return parsedSnapshot.success && parsedSnapshot.data.role === role;
}

export type PublicationAuthority = z.infer<typeof PublicationAuthoritySchema>;
export type CaptureGrant = z.infer<typeof CaptureGrantSchema>;
export type PublisherSession = z.infer<typeof PublisherSessionSchema>;
export type PublisherSnapshot = z.infer<typeof PublisherSnapshotSchema>;
export type RoleSession = z.infer<typeof RoleSessionSchema>;
export type RoleSnapshot = z.infer<typeof RoleSnapshotSchema>;

import { afterAll, describe, expect, test } from "bun:test";

import "../../../tests/setup.ts";
import { GlobalRegistrator } from "@happy-dom/global-registrator";

import { ACTIVATION_MESSAGE, type ActivationReason, UpdateCoordinator } from "./UpdateCoordinator";

afterAll(() => GlobalRegistrator.unregister());

class FakeWorker extends EventTarget {
  messages: Array<{ reason: ActivationReason; type: string }> = [];
  state: ServiceWorkerState = "installed";

  postMessage(message: { reason: ActivationReason; type: string }, transfer: Transferable[]) {
    this.messages.push(message);
    const replyPort = transfer[0] as MessagePort;
    replyPort.postMessage({ type: "IMPROMPTU_UPDATE_ACTIVATION_ACCEPTED" });
    this.state = "activated";
    this.dispatchEvent(new Event("statechange"));
  }
}

class FakeRegistration extends EventTarget {
  active: ServiceWorker | null = null;
  installing: ServiceWorker | null = null;
  waiting: ServiceWorker | null;

  constructor(waiting: FakeWorker | null) {
    super();
    this.waiting = waiting as unknown as ServiceWorker | null;
  }
}

class FakeContainer extends EventTarget {
  controller: ServiceWorker | null;
  readonly registration: FakeRegistration;

  constructor(registration: FakeRegistration, controlled: boolean) {
    super();
    this.registration = registration;
    this.controller = controlled ? ({} as ServiceWorker) : null;
  }

  async register() {
    return this.registration as unknown as ServiceWorkerRegistration;
  }
}

function coordinatorFixture({ controlled = true, waiting = true } = {}) {
  const worker = waiting ? new FakeWorker() : null;
  const registration = new FakeRegistration(worker);
  const container = new FakeContainer(registration, controlled);
  const coordinator = new UpdateCoordinator(container as unknown as ServiceWorkerContainer);
  return { container, coordinator, worker };
}

describe("UpdateCoordinator", () => {
  test("leaves first install uncontrolled and sends no activation command", async () => {
    const { container, coordinator } = coordinatorFixture({ controlled: false, waiting: false });

    await coordinator.register("/sw.js");

    expect(container.controller).toBeNull();
    expect(coordinator.updateReady).toBe(false);
  });

  test("defers a waiting update throughout an active presentation", async () => {
    const { coordinator, worker } = coordinatorFixture();
    coordinator.startSession();

    await coordinator.register("/sw.js");

    expect(coordinator.sessionActive).toBe(true);
    expect(coordinator.updateReady).toBe(true);
    expect(worker?.messages).toEqual([]);
  });

  test("activates only after explicit operator confirmation", async () => {
    const { coordinator, worker } = coordinatorFixture();
    coordinator.startSession();
    await coordinator.register("/sw.js");

    await coordinator.confirmActivation();

    expect(worker?.messages).toEqual([{ type: ACTIVATION_MESSAGE, reason: "OPERATOR_CONFIRMED" }]);
  });

  test("activates a deferred update when the presentation ends", async () => {
    const { coordinator, worker } = coordinatorFixture();
    coordinator.startSession();
    await coordinator.register("/sw.js");

    await coordinator.endSession();

    expect(worker?.messages).toEqual([{ type: ACTIVATION_MESSAGE, reason: "SESSION_ENDED" }]);
  });
});

