import type { Behavior, SlideEffect, SlideTimeline, UnsupportedEffect } from "./timeline.ts";

export type SlideRuntimeErrorCode =
  | "deck_not_animatable"
  | "invalid_behavior"
  | "invalid_group_trigger"
  | "invalid_motion_path"
  | "invalid_view_box"
  | "player_busy"
  | "target_not_found";

export class SlideRuntimeError extends Error {
  override readonly name = "SlideRuntimeError";
  constructor(
    readonly code: SlideRuntimeErrorCode,
    message: string,
  ) {
    super(message);
  }
}

export class TargetNotFoundError extends SlideRuntimeError {
  constructor(readonly elementId: string) {
    super("target_not_found", `SVG animation target was not found: ${elementId}`);
  }
}

export class DeckNotAnimatableError extends SlideRuntimeError {
  constructor() {
    super("deck_not_animatable", "The slide contains unsupported animation effects");
  }
}

export class MotionPathError extends SlideRuntimeError {
  constructor(message: string) {
    super("invalid_motion_path", message);
  }
}

export interface ViewBoxSize {
  readonly width: number;
  readonly height: number;
}

export interface RuntimeKeyframe {
  readonly opacity?: number;
  readonly clipPath?: string;
  readonly fill?: string;
  readonly transform?: string;
  readonly offset?: number;
}

export interface RuntimeAnimationOptions {
  readonly duration: number;
  readonly delay: number;
  readonly fill: "forwards";
  readonly easing: string;
}

export interface RuntimeAnimation {
  readonly finished: Promise<unknown>;
  cancel(): void;
}

export interface RuntimeAnimationElement {
  getAttribute(name: string): string | null;
  setAttribute(name: string, value: string): void;
  removeAttribute(name: string): void;
  animate(
    keyframes: readonly RuntimeKeyframe[],
    options: RuntimeAnimationOptions,
  ): RuntimeAnimation;
}

export interface RuntimeSvgRoot extends ViewBoxSize {
  getElementById(id: string): RuntimeAnimationElement | null;
}

export interface ScheduledEffect {
  readonly effect: SlideEffect;
  readonly start_ms: number;
  readonly animation_delay_ms: number;
  readonly end_ms: number;
}

export interface SlidePlayer {
  readonly groupCount: number;
  readonly currentGroup: number;
  readonly state: "ready" | "playing" | "finished";
  readonly skipped: readonly UnsupportedEffect[];
  advance(): Promise<void>;
  reset(): void;
}

export interface CreateSlidePlayerOptions {
  readonly svgRoot: SVGSVGElement;
  readonly timeline: SlideTimeline;
  readonly allowUnsupported?: boolean;
}

export interface CreateSlidePlayerFromRootOptions {
  readonly root: RuntimeSvgRoot;
  readonly timeline: SlideTimeline;
  readonly allowUnsupported?: boolean;
}

function assertNever(value: never): never {
  throw new SlideRuntimeError("invalid_behavior", `Unknown animation behavior: ${String(value)}`);
}

function validateViewBox(viewBox: ViewBoxSize): void {
  if (!(viewBox.width > 0) || !(viewBox.height > 0) || !Number.isFinite(viewBox.width + viewBox.height)) {
    throw new SlideRuntimeError("invalid_view_box", "The SVG viewBox must have finite positive dimensions");
  }
}

export function buildEffectKeyframes(
  effect: SlideEffect,
  viewBox: ViewBoxSize,
): readonly RuntimeKeyframe[] {
  const behavior = effect.behavior;
  switch (behavior.kind) {
    case "fade":
      return behavior.direction === "in" ? [{ opacity: 0 }, { opacity: 1 }] : [{ opacity: 1 }, { opacity: 0 }];
    case "color":
      return [{ fill: behavior.from_color }, { fill: behavior.to_color }];
    case "motion":
      return motionPathToKeyframes(behavior.path, viewBox);
    case "wipe": {
      const hiddenByEdge = {
        left: "inset(0 100% 0 0)",
        right: "inset(0 0 0 100%)",
        up: "inset(0 0 100% 0)",
        down: "inset(100% 0 0 0)",
      } as const;
      const shown = "inset(0 0 0 0)";
      return behavior.direction === "in"
        ? [{ clipPath: hiddenByEdge[behavior.edge] }, { clipPath: shown }]
        : [{ clipPath: shown }, { clipPath: hiddenByEdge[behavior.edge] }];
    }
    default:
      return assertNever(behavior);
  }
}

interface Point {
  readonly x: number;
  readonly y: number;
