+function wipeInset(edge: Extract<Behavior, { readonly kind: "wipe" }>["edge"]): string {
+  switch (edge) {
+    case "left":
+      return "inset(0 100% 0 0)";
+    case "right":
+      return "inset(0 0 0 100%)";
+    case "up":
+      return "inset(0 0 100% 0)";
+    case "down":
+      return "inset(100% 0 0 0)";
+    default:
+      return assertNever(edge);
+  }
