import { MotionPathError, SlideRuntimeError } from "./errors.ts";
import type { Behavior, SlideEffect, SlideTimeline } from "./timeline.ts";

export interface RuntimeKeyframe extends Keyframe {
  readonly clipPath?: string;
  readonly fill?: string;
  readonly offset?: number;
  readonly opacity?: number;
  readonly transform?: string;
}

export interface ViewportSize {
  readonly width: number;
  readonly height: number;
}

export interface ScheduledEffect {
  readonly effect: SlideEffect;
  readonly start_ms: number;
  readonly animation_delay_ms: number;
}

function assertNever(value: never): never {
  throw new SlideRuntimeError(
    "invalid_motion_path",
    `Unhandled animation variant: ${String(value)}`,
  );
}

export function entranceTargetIds(timeline: SlideTimeline): readonly string[] {
  const ids = new Set<string>();
  for (const group of timeline.click_groups) {
    for (const effect of group) {
      if (effect.effect_class === "entrance") ids.add(effect.target.svg_element_id);
    }
  }
  return [...ids];
}

export function computeGroupSchedule(effects: readonly SlideEffect[]): readonly ScheduledEffect[] {
  const schedule: ScheduledEffect[] = [];
  let previous: ScheduledEffect | undefined;
  for (const effect of effects) {
    let startMs = 0;
    if (previous === undefined) {
      if (effect.trigger !== "on_click") {
        throw new SlideRuntimeError("invalid_group_trigger", "A click group must start on click");
      }
    } else {
      switch (effect.trigger) {
        case "with_previous":
          startMs = previous.start_ms;
          break;
        case "after_previous":
          startMs = previous.animation_delay_ms + previous.effect.duration_ms;
          break;
        case "on_click":
          throw new SlideRuntimeError(
            "invalid_group_trigger",
            "Only the first group effect may start on click",
          );
        default:
          return assertNever(effect.trigger);
      }
    }
    const scheduled = {
      effect,
      start_ms: startMs,
      animation_delay_ms: startMs + effect.delay_ms,
    };
    schedule.push(scheduled);
    previous = scheduled;
  }
  return schedule;
}

function wipeInset(edge: Extract<Behavior, { readonly kind: "wipe" }>["edge"]): string {
  switch (edge) {
    case "left":
      return "inset(0 100% 0 0)";
    case "right":
      return "inset(0 0 0 100%)";
    case "up":
      return "inset(0 0 100% 0)";
    case "down":
      return "inset(100% 0 0 0)";
    default:
      return assertNever(edge);
  }
}

export function buildEffectKeyframes(
  effect: SlideEffect,
  viewport: ViewportSize,
): readonly RuntimeKeyframe[] {
  const behavior = effect.behavior;
  switch (behavior.kind) {
    case "fade":
      return behavior.direction === "in"
        ? [{ opacity: 0 }, { opacity: 1 }]
        : [{ opacity: 1 }, { opacity: 0 }];
    case "wipe": {
      const clipped = { clipPath: wipeInset(behavior.edge) };
      const open = { clipPath: "inset(0 0 0 0)" };
      return behavior.direction === "in" ? [clipped, open] : [open, clipped];
    }
    case "motion":
      return motionPathToKeyframes(behavior.path, viewport);
    case "color":
      return [{ fill: behavior.from_color }, { fill: behavior.to_color }];
    default:
      return assertNever(behavior);
  }
}

interface Point {
  readonly x: number;
  readonly y: number;
}

function tokenizeMotionPath(path: string): readonly string[] {
  const tokenPattern = /[MLCZE]|-?(?:\d+(?:\.\d*)?|\.\d+)/g;
  const tokens: string[] = [];
  let cursor = 0;
  let match = tokenPattern.exec(path);
  while (match !== null) {
    if (!/^[\s,]*$/.test(path.slice(cursor, match.index))) {
      throw new MotionPathError("Motion path contains an unsupported command or token");
    }
    tokens.push(match[0]);
    cursor = match.index + match[0].length;
    match = tokenPattern.exec(path);
  }
  if (!/^[\s,]*$/.test(path.slice(cursor))) {
    throw new MotionPathError("Motion path has invalid syntax");
  }
  return tokens;
}

function parseMotionPoints(path: string, viewport: ViewportSize): readonly Point[] {
  const tokens = tokenizeMotionPath(path);
  const points: Point[] = [];
  let first: Point | undefined;
  let index = 0;
  const number = (): number => {
    const token = tokens[index];
    if (token === undefined || /^[MLCZE]$/.test(token)) {
      throw new MotionPathError("Motion path command has missing coordinates");
    }
    index += 1;
    return Number(token);
  };
  while (index < tokens.length) {
    const command = tokens[index];
    index += 1;
    if (command === "E") {
      if (index !== tokens.length || points.length === 0) {
        throw new MotionPathError("Invalid end marker");
      }
      break;
    }
    if (command === "C") {
      throw new MotionPathError("Cubic paths cannot be represented exactly by transform keyframes");
    }
    if (command === "M" || command === "L") {
      const point = { x: number() * viewport.width, y: number() * viewport.height };
      if (command === "M") first = point;
      else if (first === undefined) throw new MotionPathError("Motion path must begin with M");
      points.push(point);
    } else if (command === "Z") {
      if (first === undefined) throw new MotionPathError("Z cannot appear before M");
      points.push(first);
    } else {
      throw new MotionPathError("Motion path contains an unsupported command");
    }
  }
  if (tokens[tokens.length - 1] !== "E") {
    throw new MotionPathError("Motion path must end with E");
  }
  return points;
}

export function motionPathToKeyframes(
  path: string,
  viewport: ViewportSize,
): readonly RuntimeKeyframe[] {
  if (viewport.width <= 0 || viewport.height <= 0) {
    throw new SlideRuntimeError("invalid_view_box", "The slide SVG viewBox must be positive");
  }
  const points = parseMotionPoints(path, viewport);
  let total = 0;
  const distances = points.map((point, index) => {
    const previous = points[index - 1];
    total += previous === undefined ? 0 : Math.hypot(point.x - previous.x, point.y - previous.y);
    return total;
  });
  return points.map((point, index) => {
    const fallbackOffset = points.length === 1 ? 0 : index / (points.length - 1);
    const distance = distances[index] ?? 0;
    return {
      transform: `translate(${Object.is(point.x, -0) ? 0 : point.x}px, ${Object.is(point.y, -0) ? 0 : point.y}px)`,
      offset: total === 0 ? fallbackOffset : distance / total,
    };
  });
}

import {
  buildEffectKeyframes,
  computeGroupSchedule,
  entranceTargetIds,
  type RuntimeKeyframe,
} from "./animation.ts";
import { DeckNotAnimatableError, MissingTargetError, SlideRuntimeError } from "./errors.ts";
import type { SlideTimeline, UnsupportedEffect } from "./timeline.ts";

export * from "./animation.ts";
export * from "./errors.ts";

export interface RuntimeAnimationOptions {
  readonly delay: number;
  readonly duration: number;
  readonly easing: string;
  readonly fill: "forwards";
}

export interface RuntimeAnimation {
  readonly finished: Promise<unknown>;
  cancel(): void;
}

export interface RuntimeAnimationElement {
  getAttribute(name: string): string | null;
  setAttribute(name: string, value: string): void;
  removeAttribute(name: string): void;
  animate(
    keyframes: readonly RuntimeKeyframe[],
    options: RuntimeAnimationOptions,
  ): RuntimeAnimation;
}

export interface RuntimeSvgRoot {
  readonly width: number;
  readonly height: number;
  getElementById(id: string): RuntimeAnimationElement | null;
}

export interface SlidePlayer {
  readonly groupCount: number;
  readonly currentGroup: number;
  readonly skipped: readonly UnsupportedEffect[];
  readonly state: "ready" | "playing" | "finished";
  advance(): Promise<void>;
  reset(): void;
}

interface PlayerOptions {
  readonly timeline: SlideTimeline;
  readonly allowUnsupported?: boolean;
}

interface RuntimePlayerOptions extends PlayerOptions {
  readonly root: RuntimeSvgRoot;
}

export interface CreateSlidePlayerOptions extends PlayerOptions {
  readonly svgRoot: SVGSVGElement;
}

interface TargetState {
  readonly element: RuntimeAnimationElement;
  readonly visibility: string | null;
}

class SlidePlayerController implements SlidePlayer {
  readonly groupCount: number;
  readonly skipped: readonly UnsupportedEffect[];
  private readonly targets = new Map<string, TargetState>();
  private readonly animations = new Set<RuntimeAnimation>();
  private groupIndex = 0;
  private playbackState: SlidePlayer["state"];

  constructor(
    private readonly root: RuntimeSvgRoot,
    private readonly timeline: SlideTimeline,
    allowUnsupported: boolean,
  ) {
    if (timeline.unsupported.length > 0 && !allowUnsupported) {
      throw new DeckNotAnimatableError();
    }
    if (root.width <= 0 || root.height <= 0) {
      throw new SlideRuntimeError("invalid_view_box", "The slide SVG viewBox must be positive");
    }
    this.groupCount = timeline.click_groups.length;
    this.skipped = allowUnsupported ? timeline.unsupported : [];
    this.playbackState = this.groupCount === 0 ? "finished" : "ready";
    for (const group of timeline.click_groups) {
      for (const effect of group) this.resolveTarget(effect.target.svg_element_id);
    }
    this.prepare();
  }

  get currentGroup(): number {
    return this.groupIndex;
  }

  get state(): SlidePlayer["state"] {
    return this.playbackState;
  }

  async advance(): Promise<void> {
    if (this.playbackState === "playing") {
      throw new SlideRuntimeError("player_busy", "The current click group is still playing");
    }
    const group = this.timeline.click_groups[this.groupIndex];
    if (group === undefined) {
      this.playbackState = "finished";
      return;
    }
    this.playbackState = "playing";
    const completions: Promise<unknown>[] = [];
    try {
      for (const scheduled of computeGroupSchedule(group)) {
        const id = scheduled.effect.target.svg_element_id;
        const target = this.targets.get(id);
        if (target === undefined) throw new MissingTargetError(id);
        if (scheduled.effect.effect_class === "entrance") {
          target.element.setAttribute("visibility", "visible");
        }
        const animation = target.element.animate(
          buildEffectKeyframes(scheduled.effect, this.root),
          {
            duration: scheduled.effect.duration_ms,
            delay: scheduled.animation_delay_ms,
            fill: "forwards",
            easing: "linear",
          },
        );
        this.animations.add(animation);
        completions.push(animation.finished);
      }
      await Promise.all(completions);
    } catch (error) {
      this.playbackState = "ready";
      throw error;
    }
    this.groupIndex += 1;
    this.playbackState = this.groupIndex === this.groupCount ? "finished" : "ready";
  }

  reset(): void {
    for (const animation of this.animations) animation.cancel();
    this.animations.clear();
    for (const target of this.targets.values()) {
      if (target.visibility === null) target.element.removeAttribute("visibility");
      else target.element.setAttribute("visibility", target.visibility);
    }
    this.groupIndex = 0;
    this.playbackState = this.groupCount === 0 ? "finished" : "ready";
    this.prepare();
  }

  private prepare(): void {
    for (const id of entranceTargetIds(this.timeline)) {
      this.resolveTarget(id).element.setAttribute("visibility", "hidden");
    }
  }

  private resolveTarget(id: string): TargetState {
    const existing = this.targets.get(id);
    if (existing !== undefined) return existing;
    const element = this.root.getElementById(id);
    if (element === null) throw new MissingTargetError(id);
    const target = { element, visibility: element.getAttribute("visibility") };
    this.targets.set(id, target);
    return target;
  }
}

export function createSlidePlayerFromRoot(options: RuntimePlayerOptions): SlidePlayer {
  return new SlidePlayerController(
    options.root,
    options.timeline,
    options.allowUnsupported === true,
  );
}

export function createSlidePlayer(options: CreateSlidePlayerOptions): SlidePlayer {
  const svgRoot = options.svgRoot;
  const root: RuntimeSvgRoot = {
    width: svgRoot.viewBox.baseVal.width,
    height: svgRoot.viewBox.baseVal.height,
    getElementById(id) {
      const element = svgRoot.getElementById(id);
      if (element === null) return null;
      return {
        getAttribute: (name) => element.getAttribute(name),
        setAttribute: (name, value) => element.setAttribute(name, value),
        removeAttribute: (name) => element.removeAttribute(name),
        animate: (keyframes, animationOptions) => element.animate([...keyframes], animationOptions),
      };
    },
  };
  if (options.allowUnsupported === undefined) {
    return createSlidePlayerFromRoot({ root, timeline: options.timeline });
  }
  return createSlidePlayerFromRoot({
    root,
    timeline: options.timeline,
    allowUnsupported: options.allowUnsupported,
  });
}

import { z } from "zod";

const SlideKeySchema = z.string().regex(/^slide_[0-9a-f]{64}$/);
const SvgElementIdSchema = z.string().regex(/^[A-Za-z][A-Za-z0-9_.:-]{0,127}$/);
const HexColorSchema = z.string().regex(/^#[0-9A-Fa-f]{6}$/);
const MotionPathSchema = z
  .string()
  .min(1)
  .max(4096)
  .regex(/^[MmLlCcQqAaHhVvZzEe0-9 ,.-]+$/);

export const FadeBehaviorSchema = z
  .strictObject({
    kind: z.literal("fade"),
    direction: z.enum(["in", "out"]),
  })
  .readonly();

export const WipeBehaviorSchema = z
  .strictObject({
    kind: z.literal("wipe"),
    direction: z.enum(["in", "out"]),
    edge: z.enum(["left", "right", "up", "down"]),
  })
  .readonly();

export const MotionBehaviorSchema = z
  .strictObject({
    kind: z.literal("motion"),
    path: MotionPathSchema,
  })
  .readonly();

export const ColorBehaviorSchema = z
  .strictObject({
    kind: z.literal("color"),
    from_color: HexColorSchema,
    to_color: HexColorSchema,
  })
  .readonly();

export const BehaviorSchema = z.discriminatedUnion("kind", [
  FadeBehaviorSchema,
  WipeBehaviorSchema,
  MotionBehaviorSchema,
  ColorBehaviorSchema,
]);

export const ResolvedTargetSchema = z
  .strictObject({
    shape_id: z.number().int().positive(),
    shape_name: z.string().min(1).max(128),
    svg_element_id: SvgElementIdSchema,
  })
  .readonly();

export const SlideEffectSchema = z
  .strictObject({
    trigger: z.enum(["on_click", "with_previous", "after_previous"]),
    effect_class: z.enum(["entrance", "emphasis", "exit", "motion"]),
    preset_id: z.number().int().min(0),
    preset_subtype: z.number().int().min(0).nullable().default(null),
    duration_ms: z.number().int().min(0).max(600_000),
    delay_ms: z.number().int().min(0).max(600_000),
    target: ResolvedTargetSchema,
    behavior: BehaviorSchema,
  })
  .readonly();

export const UnsupportedEffectSchema = z
  .strictObject({
    reason_code: z.string().regex(/^[a-z][a-z0-9_]{2,63}$/),
    preset_id: z.number().int().min(0).nullable().default(null),
    detail: z.string().min(1).max(512),
  })
  .readonly();

export const SlideTransitionSchema = z
  .strictObject({
    kind: z.string().regex(/^[a-z][a-z0-9_]{1,31}$/),
    advance_on_click: z.boolean().default(true),
  })
  .readonly();

export const SlideTimelineSchema = z
  .strictObject({
    slide_key: SlideKeySchema,
    click_groups: z.array(z.array(SlideEffectSchema).readonly()).readonly().default([]),
    transition: SlideTransitionSchema.nullable().default(null),
    unsupported: z.array(UnsupportedEffectSchema).readonly().default([]),
  })
  .readonly();

export type FadeBehavior = z.infer<typeof FadeBehaviorSchema>;
export type WipeBehavior = z.infer<typeof WipeBehaviorSchema>;
export type MotionBehavior = z.infer<typeof MotionBehaviorSchema>;
export type ColorBehavior = z.infer<typeof ColorBehaviorSchema>;
export type Behavior = z.infer<typeof BehaviorSchema>;
export type ResolvedTarget = z.infer<typeof ResolvedTargetSchema>;
export type SlideEffect = z.infer<typeof SlideEffectSchema>;
export type UnsupportedEffect = z.infer<typeof UnsupportedEffectSchema>;
export type SlideTransition = z.infer<typeof SlideTransitionSchema>;
export type SlideTimeline = z.infer<typeof SlideTimelineSchema>;

export function parseSlideTimeline(input: unknown): SlideTimeline {
  return SlideTimelineSchema.parse(input);
}

